#!/usr/bin/env python3
"""VERSION is the one version authority. This derives app/version.h and checks that
app/application.fam carries the same major.minor (fap_version holds only two parts).

Usage: tools/version.py [--check]
"""

import re
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent


def render(version):
    return (
        "/* Generated by tools/version.py from VERSION. Do not edit. */\n"
        "#pragma once\n\n"
        f'#define PRISMATIC_VERSION "{version}"\n'
    )


def main(argv):
    version = (ROOT / "VERSION").read_text().strip()
    if not re.fullmatch(r"\d+\.\d+\.\d+", version):
        print(f"VERSION is not MAJOR.MINOR.PATCH: {version!r}", file=sys.stderr)
        return 1
    header = ROOT / "app" / "version.h"
    fam = (ROOT / "app" / "application.fam").read_text()
    major_minor = ".".join(version.split(".")[:2])
    errors = []
    m = re.search(r'fap_version="([^"]+)"', fam)
    if not m or m.group(1) != major_minor:
        errors.append(f'app/application.fam fap_version must be "{major_minor}"')
    if "--check" in argv:
        if not header.exists() or header.read_text() != render(version):
            errors.append("app/version.h drifted from VERSION (run tools/version.py)")
    else:
        header.write_text(render(version))
    for e in errors:
        print(e, file=sys.stderr)
    return 1 if errors else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
